let sequence=0
async function load(){const seq=++sequence;loading.value=true;error.value='';selected.value=[];try{const p=new URLSearchParams({page:String(page.value),page_size:String(pageSize.value)});for(const [k,v] of Object.entries(filters))if(v!==''&&v!=null)p.set(k,String(v));p.set('grouped','true');const d=await api('/procurement/'+view.value+'?'+p);if(seq!==sequence)return;rows.value=d.rows;total.value=d.total}catch(e){if(seq===sequence)error.value=(e as Error).message}finally{if(seq===sequence)loading.value=false}}
