async function openPlan(row?:any){newPlanRequest.value=uuid();newPlanFingerprint='';for(const c of routeColumns)newPlanQuantities[c.key]=0;planId.value=row?.id||null;Object.assign(planForm,{product_id:row?.product_id||null,store:row?.store||filters.store||options.stores[0]||'',country:row?.country||filters.country||'UK',channel:row?.channel||filters.channel||'air',warehouse_id:row?.warehouse_id||Number(filters.warehouse_id)||options.warehouses[0]?.id||null,quantity:row?.quantity||1,buyer:row?.buyer||'',note:row?.note||'',revision:row?.revision||null});planError.value='';planDialog.value=true;if(row)productOptions.value=[{id:row.product_id,code:row.code,name:row.name}];else await findProducts('')}
async function savePlan(){
 if(planBusy.value)return
