 if(planId.value){if(!Number.isInteger(planForm.quantity)||planForm.quantity<1){planError.value='请填写有效的计划数量';return}}
 else{
  const routes:any[]=[]
  for(const c of routeColumns){const n=newPlanQuantities[c.key]??0;if(!Number.isInteger(n)||n<0||n>10000000){planError.value='渠道数量必须是 0 至 10000000 的整数';return}if(n){const [country,channel]=c.key.split('_');routes.push({country,channel,quantity:n})}}
