function breakdown(items:any[]){const sums:Record<string,number>={};for(const a of items){const label=`${options.countries[a.country]}${options.channels[a.channel]}`;sums[label]=(sums[label]||0)+a.quantity}return Object.entries(sums).map(([k,v])=>`${k} ${v}`).join(' ｜ ')}
