async function saveReceipt(){if(receiptBusy.value)return;if(!Number.isInteger(receiptQty.value)||!receiptQty.value||receiptQty.value<1){receiptError.value='请填写本次实际到货数量';return}const f=JSON.stringify([receiptQty.value,receiptNote.value]);if(receiptFingerprint&&f!==receiptFingerprint)receiptId.value=uuid();receiptFingerprint=f;receiptBusy.value=true;receiptError.value='';try{const d=await api(`/procurement/orders/${receiptContext.value.id}/receive`,{request_id:receiptId.value,revision:receiptContext.value.revision,quantity:receiptQty.value,note:receiptNote.value});receiptDialog.value=false;ElMessage.success(`本次 ${d.received_delta} 件已入库，已安排的发货计划自动补锁库存`);await load()}catch(e){receiptError.value=(e as Error).message}finally{receiptBusy.value=false}}
