async function saveReceipts(){
 if(receiptsBusy.value)return
 if(receiptsRows.value.some(r=>r.arrival!=null&&(!Number.isInteger(r.arrival)||r.arrival<0||r.arrival>r.remaining))){receiptsError.value='本次到货须为整数，不能超过该采购单的待到货量';return}
 if(receiptsTotal.value<=0){receiptsError.value='请填写本次实际到货数量，或点击“全部”填充';return}
 const body={orders:receiptsRows.value.map(r=>({id:r.id,revision:r.revision,quantity:r.arrival??0})),note:receiptsNote.value};const fingerprint=JSON.stringify(body)
