 try{const d=await api('/procurement/orders/batch-receive',{...body,request_id:receiptsId.value});receiptsDialog.value=false;ElMessage.success(`已登记 ${d.updated} 条采购明细到货，共 ${d.received_delta} 件已入本地仓库`);await load()}catch(e){receiptsError.value=(e as Error).message}finally{receiptsBusy.value=false}
