 for(const line of batch.children){const key=`${line.product_id}:${line.store}:${line.warehouse_id}`;if(!groups.has(key))groups.set(key,{key,product_id:line.product_id,store:line.store,warehouse_id:line.warehouse_id,note:[...new Set(batch.children.filter((p:any)=>p.product_id===line.product_id&&p.store===line.store&&p.warehouse_id===line.warehouse_id).map((p:any)=>p.note).filter(Boolean))].join(' / '),quantities:{},original:{}});const row=groups.get(key),route=line.country+'_'+line.channel;row.quantities[route]=(row.quantities[route]||0)+line.quantity;(row.original[route]??=[]).push(line)}
 editorRows.value=[...groups.values()];productOptions.value=batch.products.map((p:any)=>({id:p.product_id,code:p.code,name:p.name}));editorOpen.value=true
}
