 if(editorBusy.value)return
 const items:any[]=[],seen=new Set<string>();editorError.value=''
 for(const row of editorRows.value){if(!row.product_id||!row.store||!row.warehouse_id){editorError.value='请选择每个 SKU 的标品、店铺和收货仓库';return}const key=`${row.product_id}:${row.store}:${row.warehouse_id}`;if(seen.has(key)){editorError.value='同一标品、店铺和仓库只能保留一行';return}seen.add(key)
  for(const c of routeColumns){const quantity=row.quantities[c.key]??0;if(!Number.isInteger(quantity)||quantity<0||quantity>10000000){editorError.value='渠道数量必须是 0 至 10000000 的整数';return}if(quantity){const [country,channel]=c.key.split('_');items.push({id:row.original[c.key]?.[0]?.id||null,product_id:row.product_id,store:row.store,warehouse_id:row.warehouse_id,country,channel,quantity,note:row.note||''})}}
 }
 if(!items.length){editorError.value='至少保留一个渠道数量；删除整个计划请使用列表中的删除按钮';return}
 editorBusy.value=true
 try{await api(`/procurement/plan-batches/${encodeURIComponent(editorContext.value.batch_code)}/update`,{buyer:editorBuyer.value||'',plans:editorContext.value.children.map((p:any)=>({id:p.id,revision:p.revision})),items});editorOpen.value=false;await load();ElMessage.success('整批采购计划已保存')}catch(e){editorError.value=(e as Error).message}finally{editorBusy.value=false}
}
async function deletePlanBatch(row:any){if(!editableBatch(row))return;try{await ElMessageBox.confirm(`确定删除未处理的采购计划【${row.batch_code}】及其全部 SKU？`,'删除采购计划',{type:'warning',confirmButtonText:'确定删除'});await api(`/procurement/plan-batches/${encodeURIComponent(row.batch_code)}/delete`,{plans:row.children.map((p:any)=>({id:p.id,revision:p.revision}))});await load();ElMessage.success('采购计划已删除')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
const planLogsOpen=ref(false),planLogsBusy=ref(false),planLogRows=ref<any[]>([]),planLogsPage=ref(1),planLogsPageSize=ref(25),planLogsTotal=ref(0),planLogsCode=ref(''),planLogsError=ref('')
async function showPlanLogs(row:any){planLogsCode.value=row.batch_code;planLogsPage.value=1;planLogsOpen.value=true;await loadPlanLogs()}
async function loadPlanLogs(){planLogsBusy.value=true;planLogsError.value='';try{const d=await api(`/procurement/plan-batches/${encodeURIComponent(planLogsCode.value)}/logs?page=${planLogsPage.value}&page_size=${planLogsPageSize.value}`);planLogRows.value=d.rows;planLogsTotal.value=d.total}catch(e){planLogsError.value=(e as Error).message}finally{planLogsBusy.value=false}}
async function deleteOrderDocument(row:any){try{await ElMessageBox.confirm(`确定删除采购单【${row.number}】？来源采购计划对应商品将恢复待处理。`,'删除采购单',{type:'warning',confirmButtonText:'确定删除'});await api(`/procurement/flow/orders/${row.items[0].id}/delete`,{items:row.items.map((i:any)=>({id:i.id,revision:i.revision}))});await load();ElMessage.success('采购单已删除，来源采购计划已恢复')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
const exportBusy=ref(false)
async function exportExcel(){exportBusy.value=true;try{const params=new URLSearchParams({view:view.value});for(const [k,v]of Object.entries(filters))if(v!==''&&v!=null)params.set(k,String(v));const response=await fetch('/api/procurement/export?'+params);if(!response.ok){const d=await response.json();throw new Error(d.detail||'导出失败')}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;const encoded=response.headers.get('Content-Disposition')?.match(/filename\*=UTF-8''(.+)/)?.[1];link.download=encoded?decodeURIComponent(encoded):'采购导出.xlsx';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);ElMessage.success('Excel 已导出')}catch(e){ElMessage.error((e as Error).message)}finally{exportBusy.value=false}}

</script>
