 <template v-if="true"><TableReset table-key="ProcurementPanel/plan-logs"/><el-table :data="planLogRows" v-loading="planLogsBusy" border data-width-key="ProcurementPanel/plan-logs" @header-dragend="(w:number,_o:number,c:any)=>tableWidths.resize('plan-logs',w,c)" @header-contextmenu="(c:any,e:MouseEvent)=>tableWidths.resetColumn('plan-logs',c,e)">
 <el-table-column column-key="time" label="操作时间" :width="tableWidths.width('plan-logs','time',180)"><template #default="{row}">{{time(row.created_at)}}</template></el-table-column><el-table-column column-key="actor" prop="actor" label="操作人" :width="tableWidths.width('plan-logs','actor',110)"/><el-table-column column-key="title" prop="title" label="操作" :width="tableWidths.width('plan-logs','title',180)"/><el-table-column column-key="detail" label="详情" :width="tableWidths.width('plan-logs','detail')"><template #default="{row}"><span v-if="row.detail.filename">{{row.detail.filename}}</span><span v-if="row.detail.buyer">采购员：{{row.detail.buyer}} </span><span v-if="row.detail.quantity!=null">数量：{{row.detail.quantity}} </span><span v-if="row.detail.orders">{{row.detail.orders.join(' / ')}}</span><details v-if="row.detail.before||row.detail.after"><summary>查看变更明细</summary><pre class="plan-log-detail">{{JSON.stringify({修改前:row.detail.before,修改后:row.detail.after},null,2)}}</pre></details></template></el-table-column>
