 <el-dialog v-model="sourceDialog" :title="sourceTitle" width="900px">
 <template v-if="true"><TableReset table-key="ProcurementPanel/table-4"/><el-table border data-width-key="ProcurementPanel/table-4" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-4', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-4', column, event)" :data="sourceRows"><el-table-column :column-key="'store'" :width="tableWidths.width('table-4', 'store', undefined)" prop="store" label="店铺"/><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-4', 'column-2', undefined)" label="渠道"><template #default="{row}">{{options.countries[row.country]}}{{options.channels[row.channel]}}</template></el-table-column><el-table-column :column-key="'warehouse_name'" :width="tableWidths.width('table-4', 'warehouse_name', undefined)" prop="warehouse_name" label="仓库"/><el-table-column :column-key="'quantity'" :width="tableWidths.width('table-4', 'quantity', undefined)" prop="quantity" label="计划数量" align="center"/><el-table-column :column-key="'column-5'" :width="tableWidths.width('table-4', 'column-5', undefined)" label="状态 / 采购单" min-width="190"><template #default="{row}">{{row.status==='pending'?'待处理':'已处理'}}<div>{{row.order_number}}</div></template></el-table-column><el-table-column :column-key="'column-6'" v-if="admin" label="操作" :width="tableWidths.width('table-4', 'column-6', '80')"><template #default="{row}"><el-button link type="primary" :disabled="!sourceEditable||row.status!=='pending'" @click="openPlan(row)">编辑</el-button></template></el-table-column></el-table></template>
 </el-dialog>
 <el-dialog v-model="batchDialog" :title="batchTitle" width="700px" :close-on-click-modal="false" :show-close="!batchBusy" :close-on-press-escape="!batchBusy"><el-alert v-if="batchError" :title="batchError" type="error" :closable="false"/><p>已选择 {{new Set(batchRows.map(r=>r.number)).size}} 张采购单，共 {{batchRows.length}} 条商品明细</p><p v-if="batchAction==='dispatch'" class="batch-explain">选中的采购单按店铺、国家、渠道和仓库生成发货计划。选择锁定时，库存不足会列出缺货商品并停止生成；选择不锁定时可先创建计划，后续通过手动出库校验库存。</p><p v-else class="batch-explain">{{batchAction==='purchased'?'确认已采购后，状态改为“待到货”，并计入仓库待到货量。':'恢复为“待采购”，移除对应待到货量。'}} 已登记到货的采购单请取消勾选。</p><div v-if="batchAction==='dispatch'" class="batch-stock-choice"><b>是否锁定库存？</b><el-radio-group v-model="batchLockInventory" :disabled="batchBusy"><el-radio :value="true">是，校验并锁定库存</el-radio><el-radio :value="false">否，不锁定库存</el-radio></el-radio-group></div><template v-if="true"><TableReset table-key="ProcurementPanel/table-5"/><el-table border data-width-key="ProcurementPanel/table-5" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-5', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-5', column, event)" :data="batchRows" max-height="350"><el-table-column :column-key="'number'" prop="number" label="采购单" :width="tableWidths.width('table-5', 'number', '180')"/><el-table-column :column-key="'code'" :width="tableWidths.width('table-5', 'code', undefined)" prop="code" label="标品编码" min-width="220"/><el-table-column :column-key="'quantity'" prop="quantity" label="采购量" :width="tableWidths.width('table-5', 'quantity', '90')" align="center"/><el-table-column :column-key="'received'" prop="received" label="已到货" :width="tableWidths.width('table-5', 'received', '90')"/></el-table></template><template #footer><el-button :disabled="batchBusy" @click="batchDialog=false">取消</el-button><el-button type="primary" :loading="batchBusy" @click="saveBatch">确认{{batchTitle}}</el-button></template></el-dialog>
 <el-dialog v-model="receiptsDialog" :title="receiptsTitle" width="min(1200px,95vw)" :close-on-click-modal="false" :show-close="!receiptsBusy" :close-on-press-escape="!receiptsBusy">
 <p>已选择 {{new Set(receiptsRows.map(r=>r.number)).size}} 张采购单，{{receiptsRows.length}} 条商品明细。本次到货合计 <strong>{{receiptsTotal}}</strong> 件。</p>
