 <template v-if="true"><TableReset table-key="ProcurementPanel/table-6"/><el-table border data-width-key="ProcurementPanel/table-6" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-6', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-6', column, event)" :data="receiptsRows" max-height="460" row-key="id">
 <el-table-column :column-key="'warehouse_name'" prop="warehouse_name" label="采购仓库" :width="tableWidths.width('table-6', 'warehouse_name', '130')"/>
 <el-table-column :column-key="'column-2'" label="图片" :width="tableWidths.width('table-6', 'column-2', '75')"><template #default="{row}"><el-image v-if="row.image_url" :src="row.image_url" fit="contain" class="product-image"/><span v-else class="muted">暂无图片</span></template></el-table-column>
 <el-table-column :column-key="'column-3'" :width="tableWidths.width('table-6', 'column-3', undefined)" label="品名 / 标品编码" min-width="240"><template #default="{row}"><strong>{{row.name}}</strong><div>{{row.code}}</div><small class="muted">{{row.number}} · {{row.supplier}}</small></template></el-table-column>
 <el-table-column :column-key="'column-4'" label="店铺" :width="tableWidths.width('table-6', 'column-4', '120')"><template #default="{row}">{{[...new Set(row.allocations.map((p:any)=>p.store))].join(' / ')}}</template></el-table-column>
 <el-table-column :column-key="'quantity'" prop="quantity" label="采购量" :width="tableWidths.width('table-6', 'quantity', '85')" align="center"/><el-table-column :column-key="'received'" prop="received" label="已到货" :width="tableWidths.width('table-6', 'received', '85')" align="center"/><el-table-column :column-key="'remaining'" prop="remaining" label="待到货量" :width="tableWidths.width('table-6', 'remaining', '95')" align="center"/>
 <el-table-column :column-key="'column-8'" :width="tableWidths.width('table-6', 'column-8', '195')" align="center"><template #header>本次到货量 <el-button link type="primary" :disabled="receiptsBusy" @click="fillAllReceipts">全部</el-button></template><template #default="{row}"><el-input-number v-model="row.arrival" :aria-label="`本次到货量 ${row.number}`" :min="0" :max="row.remaining" :precision="0" :controls="false" :disabled="receiptsBusy||!row.remaining" style="width:150px" placeholder="实际到货数量"/></template></el-table-column>
 </el-table></template>
 <p class="batch-explain">“全部”填入剩余待到货量；未收货时等于采购量。空白或 0 不入库。确认后更新本地库存，全部收齐自动标为已到货，部分收货保持待到货。</p>
