 </el-dialog>
 <el-dialog v-model="receiptDialog" title="登记到货" width="580px" :close-on-click-modal="false" :show-close="!receiptBusy" :close-on-press-escape="!receiptBusy"><div class="order-context"><strong>{{receiptContext?.number}} · {{receiptContext?.name}}</strong><p>收货仓库：{{receiptContext?.warehouse_name}}</p><p>采购 {{receiptContext?.quantity}} 件 · 已到货 {{receiptContext?.received}} 件 · 剩余 {{(receiptContext?.quantity||0)-(receiptContext?.received||0)}} 件</p></div><el-alert v-if="receiptError" type="error" :title="receiptError" :closable="false"/><el-form label-position="top" :disabled="receiptBusy"><el-form-item label="本次实际到货数量" required><el-input-number v-model="receiptQty" :min="1" :max="(receiptContext?.quantity||0)-(receiptContext?.received||0)" :precision="0"/></el-form-item><el-form-item label="备注 / 到货单据号"><el-input v-model="receiptNote" type="textarea" maxlength="1000"/></el-form-item></el-form><p class="batch-explain">填写本次新增到货量。确认后入本地仓库；部分到货为待到货，全部到货自动变为已到货。提前生成过发货计划的数量不会重复生成。</p><template #footer><el-button :disabled="receiptBusy" @click="receiptDialog=false">取消</el-button><el-button type="primary" :loading="receiptBusy" @click="saveReceipt">确认到货并入库</el-button></template></el-dialog>
 <el-dialog v-model="planDialog" :title="planId?'编辑采购计划':'新增采购计划'" width="620px" :close-on-click-modal="false" :show-close="!planBusy" :close-on-press-escape="!planBusy"><el-alert v-if="planError" type="error" :title="planError" :closable="false"/><el-form label-position="top" :disabled="planBusy"><el-form-item label="标品" required><el-select v-model="planForm.product_id" filterable remote :remote-method="findProducts" :loading="productLoading" placeholder="搜索标品编码或中文品名" style="width:100%"><el-option v-for="p in productOptions" :key="p.id" :value="p.id" :label="`${p.code} · ${p.name}`"/></el-select></el-form-item><div class="form-grid"><el-form-item label="店铺" required><el-select v-model="planForm.store"><el-option v-for="s in options.stores" :key="s" :value="s" :label="s"/></el-select></el-form-item><el-form-item v-if="planId" label="国家" required><el-select v-model="planForm.country"><el-option v-for="(n,k) in options.countries" :key="k" :value="k" :label="n"/></el-select></el-form-item><el-form-item v-if="planId" label="发货渠道" required><el-select v-model="planForm.channel"><el-option v-for="(n,k) in options.channels" :key="k" :value="k" :label="`${options.countries[planForm.country]}${n}`"/></el-select></el-form-item><el-form-item label="收货仓库" required><el-select v-model="planForm.warehouse_id"><el-option v-for="w in options.warehouses" :key="w.id" :value="w.id" :label="w.name"/></el-select></el-form-item></div><el-form-item label="备注"><el-input v-model="planForm.note" aria-label="采购计划备注" type="textarea" :rows="2" maxlength="1000" show-word-limit/></el-form-item><el-form-item label="采购员"><el-select v-model="planForm.buyer" placeholder="指定采购员" clearable :value-on-clear="''"><el-option v-for="u in options.buyers" :key="u.username" :value="u.username" :label="u.username"/></el-select></el-form-item><el-form-item v-if="planId" label="计划采购量" required><el-input-number v-model="planForm.quantity" :min="1" :max="10000000" :precision="0"/></el-form-item><template v-else><div class="new-plan-routes"><el-form-item v-for="c in routeColumns" :key="c.key" :label="c.name"><el-input-number v-model="newPlanQuantities[c.key]" :min="0" :max="10000000" :precision="0" :aria-label="c.name+'采购数量'"/></el-form-item></div><div class="new-plan-total">计划采购量合计 <strong>{{newPlanTotal}}</strong></div></template></el-form><template #footer><el-button :disabled="planBusy" @click="planDialog=false">取消</el-button><el-button type="primary" :loading="planBusy" @click="savePlan">保存计划</el-button></template></el-dialog>
 <el-dialog v-model="generateDialog" title="生成采购单" width="min(1150px,95vw)" :close-on-click-modal="false" :show-close="!generateBusy" :close-on-press-escape="!generateBusy">
 <p class="purchase-note">已选择 {{versions.length}} 条计划，{{groups.length}} 条商品明细，将按供应商生成 {{supplierGroups.length}} 张采购单。同一供应商共用编号及预计到货日期；默认待采购。</p>
 <el-alert v-if="generateError" type="error" :title="generateError" :closable="false"/>
 <el-form :disabled="generateBusy">
 <section v-for="supplier in supplierGroups" :key="supplier.key" class="generation-group">
 <div class="supplier-heading"><strong>供应商采购单 · {{supplier.items.length}} 条商品</strong><div class="generate-fields"><el-form-item label="供应商" required><el-input :model-value="supplier.supplier" @change="(v:string)=>setSupplier(supplier,v)" maxlength="500" placeholder="填写供应商名称"/></el-form-item><el-form-item label="共用预计到货日期" required><el-date-picker :model-value="supplier.items[0].expected_date" @update:model-value="(v:any)=>setSupplierDate(supplier,v)" type="date" value-format="YYYY-MM-DD" placeholder="此供应商商品共用日期"/></el-form-item></div></div>
 <div v-for="g in supplier.items" :key="g.key" class="supplier-product"><div class="generation-title"><el-image v-if="g.image_url" :src="g.image_url" fit="contain" class="product-image"/><div><strong>{{g.code}} · {{g.name}}</strong><p>{{g.warehouse_name}} · 计划采购 {{g.quantity}} 件</p><small>{{breakdown(g.allocations)}}</small><div class="muted">计划批次：{{[...new Set(g.allocations.map((a:any)=>a.batch_code))].join(' / ')}}</div></div></div><div class="generate-fields"><el-form-item label="采购单价 (¥)" required><el-input-number v-model="g.unit_cost" :min="0" :max="100000000" :precision="4"/></el-form-item><el-form-item label="其他费用 (¥)"><el-input-number v-model="g.extra_cost" :min="0" :max="100000000" :precision="4"/></el-form-item></div><div>货值 ¥{{money(g.quantity*(g.unit_cost||0))}} · 合计费用 ¥{{money(g.quantity*(g.unit_cost||0)+(g.extra_cost||0))}}</div></div>
 </section></el-form><template #footer><el-button :disabled="generateBusy" @click="generateDialog=false">取消</el-button><el-button type="primary" :loading="generateBusy" @click="generate">确认生成采购单</el-button></template></el-dialog>
 <el-dialog v-model="documentDialog" :title="'编辑采购单 · '+(documentContext?.number||'')" width="min(1250px,95vw)" :close-on-click-modal="false" :show-close="!documentBusy" :close-on-press-escape="!documentBusy">
<el-alert v-if="documentError" :title="documentError" type="error" :closable="false"/>
