<template v-if="true"><TableReset table-key="ProcurementPanel/document-editor"/><el-table border data-width-key="ProcurementPanel/document-editor" :data="documentRows" max-height="450" @header-dragend="(width:number,_old:number,column:any)=>tableWidths.resize('document-editor',width,column)" @header-contextmenu="(column:any,event:MouseEvent)=>tableWidths.resetColumn('document-editor',column,event)">
<el-table-column column-key="product" label="标品编码 / 品名" min-width="230" :width="tableWidths.width('document-editor','product',undefined)"><template #default="{row}"><b>{{row.code}}</b><div>{{row.name}}</div><small>{{row.warehouse_name}}</small></template></el-table-column>
<el-table-column column-key="quantity" prop="quantity" label="计划采购量" :width="tableWidths.width('document-editor','quantity',100)" align="center"/>
<el-table-column column-key="status" label="状态" :width="tableWidths.width('document-editor','status',140)"><template #default="{row}"><el-select v-model="row.status"><el-option v-for="(n,k) in options.states" :key="k" :value="k" :label="n"/></el-select></template></el-table-column>
<el-table-column column-key="received" label="累计到货量" :width="tableWidths.width('document-editor','received',150)" align="center"><template #default="{row}"><el-input-number v-model="row.received" :min="documentContext.items.find((i:any)=>i.id===row.id).received" :max="row.quantity" :precision="0" :controls="false" style="width:115px" @update:model-value="documentReceived(row)"/></template></el-table-column>
